/* MIR/27 1.0. Source text is always escaped. No questions are bundled in this public file. */
(()=>{'use strict';
document.documentElement.dataset.mirVersion=MIRCore.VERSION;
const C=MIRCore,L=MIRLearning,S=MIRStore,$=s=>document.querySelector(s),main=$('#main');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tidy=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim().toLowerCase();
let bank=null,state=null,index=new Map(),ready=false,busy=false,currentSession=null,enteredKey='',enteredAt=0,importPayload=null,importing=false;
const WEB='https://mir-2027.vercel.app';const importNonce=new URLSearchParams(location.hash.slice(1)).get('import');
const filters={text:'',subject:'',year:'',status:'all',images:false,favorites:false,page:0};let readingFilter='',readingPage=0,atlasPage=0,atlasScope='all',atlasSearch='',atlasMetadata=null,atlasRequest=0,atlasMode='';
const navItems=[['today','Hoy'],['bank','Banco de preguntas'],['ampliaciones','Explicaciones ampliadas'],['quality','Revisión y fuentes'],['topics','Temas y lecturas'],['review','Mi repaso'],['atlas','Atlas visual'],['exams','Simulacros'],['progress','Mi progreso'],['library','Biblioteca y copias']];
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,4500);}
function badge(t,kind=''){return`<span class="badge ${kind}">${esc(t)}</span>`;}
function statusText(q){if(q.duplicateOf)return'Otra versión documental';if(q.sourceDiscrepancy)return'Discrepancia entre fuentes';if(q.isChallenged||q.challengeStatus==='pending')return'Impugnación pendiente según la fuente';if(q.isAnnulled)return'Anulada según la fuente';if(q.imageRequired&&!q.images?.length&&!q.image)return'Falta imagen';if(!C.eligible(q))return'Revisión pendiente';return q.status==='variante_matematica'?'Ejercicio original':'Fuente histórica';}
function lookup(id){return index.get(id);}
function route(){return(location.hash||'#today').slice(1).split('?')[0];}
function go(view){if(location.hash==='#'+view)render();else location.hash=view;}
function heading(title,sub=''){return`<div class="page-heading"><div><p class="eyebrow">TU ENTRENAMIENTO MÉDICO PERSONAL</p><h1>${esc(title)}</h1>${sub?`<p class="muted">${esc(sub)}</p>`:''}</div></div>`;}
function shell(title,body,sub=''){main.innerHTML=heading(title,sub)+body;$('#nav').querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===route()));main.querySelectorAll('[data-media]').forEach(el=>observeImage(el));recordVisibleLearning();}
function button(action,text,cls='ghost',extra=''){return`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;}
function renderNav(){const allowed=ready&&!S.recovering;$('#nav').innerHTML=allowed?navItems.map(([id,name])=>`<button data-view="${id}" class="${route()===id?'active':''}">${name}</button>`).join(''):'';$('#logout').hidden=S.local||!S.user;$('#mode').textContent=S.local?'LOCAL · PRIVADO':S.offline?'SESIÓN SIN CONEXIÓN':'WEB · ACCESO PRIVADO';}
function applyPrefs(){document.documentElement.style.setProperty('--reader-scale',String(state?.preferences.fontScale||1));document.documentElement.classList.toggle('focus-mode',!!state?.preferences.focus);}
async function save(){if(!state)return;$('#save-label').textContent='Guardando…';try{const next=await S.saveState(state);state=C.merge(state,next);$('#save-label').textContent=S.local?'Guardado en este dispositivo':S.pending?'Guardado aquí · pendiente de sincronizar':'Sincronizado';}catch(e){$('#save-label').textContent='Cambios pendientes de sincronizar';toast(e.message);}}
function refs(d){const list=d.references||[];if(!list.length)return`<p class="muted small">${d.origin?.includes('original')?'Elaboración original; no se atribuye a un examen oficial.':'La ficha no especifica una referencia de página.'}</p>`;return`<details class="sources"><summary>Fuentes y página exacta (${list.length})</summary>${list.map(r=>`<p><strong>${esc(r.title||r.id||'Documento')}</strong>${r.pdfPage?` · PDF p. ${esc(r.pdfPage)}${r.pdfPageEnd&&r.pdfPageEnd!==r.pdfPage?'–'+esc(r.pdfPageEnd):''}`:''}${r.printedPage?` · impresa p. ${esc(r.printedPage)}`:''}${r.yearLabel?` · rótulo ${esc(r.yearLabel)}`:''}<br><span class="muted small">${esc(r.file||'')}</span>${r.url&&/^https:\/\//.test(r.url)?` <a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Abrir referencia</a>`:''}${S.local&&r.file&&bank.sources.some(x=>x.id===r.id&&x.originalIncluded)?` <a href="./biblioteca_originales/${encodeURIComponent(r.file)}${r.pdfPage?'#page='+encodeURIComponent(r.pdfPage):''}" target="_blank" rel="noopener">Abrir original en el paquete local</a>`:''}</p>`).join('')}</details>`;}
function paragraph(t){return`<div class="source-text">${esc(t)}</div>`;}
function correction(q,a,scored=C.eligible(q),attemptId=null){
 q=learningContent(q);
 const key=q.answer,keyText=Number.isInteger(key)&&q.options[key]?q.options[key]:'La fuente no aporta una clave única',isCorrect=a?.selected!=null&&a.selected===key;
 const reviewed=q.teachingReview&&q.explanation,discussion=C.optionDiscussion(q);
 const comments=q.sourceCommentaries?.length?q.sourceCommentaries:[{title:'Comentario del documento',text:q.commentary||q.explanation||'',pdfPage:q.references?.[0]?.pdfPage}];
 const options=q.options.map((text,i)=>{const r=discussion.reasons[i];if(r.kind==='context'||r.kind!=='authored'&&!r.evidence.length)return'';return `<details class="option-reason" ${r.kind==='authored'&&(i===key||i===a?.selected)?'open':''}><summary><span class="badge ${i===key&&scored?'good':''}">${i===key?'Clave de la fuente':'Alternativa'}</span> ${esc(text)}</summary>${r.sections?`<div class="option-teaching"><h4>Por qué encaja o se descarta</h4>${paragraph(r.sections.reason)}<h4>Cómo distinguirla</h4>${paragraph(r.sections.contrast)}<p class="memory-trap"><strong>Trampa de examen:</strong> ${esc(r.sections.pitfall)}</p></div>`:r.kind==='authored'?paragraph(r.text):`${r.kind==='related-excerpt'?'<p class="small muted">Pasaje relacionado por su contenido; no es una explicación individual elaborada.</p>':''}${r.evidence.map(e=>`<blockquote>${esc(e.text)}</blockquote><p class="small muted">Extracto de la fuente${e.pdfPage?' · PDF p. '+esc(e.pdfPage):''}. Numeración del documento original.</p>`).join('')}`}</details>`;}).join('');
 const shared=discussion.shared.length?`<details class="shared-evidence commentary"><summary>Comparaciones del comentario original</summary><p class="small muted">Estos pasajes hablan de varias alternativas y se presentan una sola vez.</p>${discussion.shared.map(e=>`<p><strong>${e.indices.map(i=>esc(q.options[i])).join(' · ')}</strong></p><blockquote>${esc(e.text)}</blockquote>${e.pdfPage?`<p class="small muted">PDF p. ${esc(e.pdfPage)} · numeración del documento original.</p>`:''}`).join('')}</details>`:'';
 const pending=discussion.pending.length?`<p class="small muted pending-options">Quedan por ampliar con explicación propia: ${discussion.pending.map(i=>esc(q.options[i])).join(' · ')}. El comentario completo se conserva a continuación.</p>`:'';
 const source=`<div class="historical-commentaries"><h3>Comentario de tus documentos</h3>${comments.map((x,i)=>`<details class="commentary" ${!reviewed&&i===0?'open':''}><summary>${esc(x.title||'Comentario de la fuente')}${x.yearLabel?' · '+esc(x.yearLabel):''}${x.pdfPage?' · p. '+esc(x.pdfPage):''}</summary><p class="muted small">Texto histórico de la fuente; puede contener diferencias respecto a la práctica actual.</p>${x.options&&Number.isInteger(x.answer)?`<p class="small muted">Clave en esta fuente: ${esc(x.options[x.answer])}.</p>`:''}${paragraph(x.text)}</details>`).join('')}</div>`;
 return`<section class="correction" data-learning-concept="${esc(L.preciseKey(q)||'')}"><div class="correction-top">${badge(!scored?'Estudio con observaciones · sin puntuación':a?.selected==null?'Sin respuesta':isCorrect?'Acertada':'Para repasar',scored&&isCorrect?'good':'warn')}<h3>${q.origin?.includes('original')?'Resultado del ejercicio':'Respuesta de la fuente'}</h3></div><p class="answer-key">${esc(keyText)}</p>${a?.selected!=null?`<p>Tu elección: <strong>${esc(q.options[a.selected]||'')}</strong>.</p>`:''}${q.sourceDiscrepancy?'<p class="notice warning">Hay una discrepancia pendiente. Compara los comentarios y las claves atribuidas a cada fuente.</p>':''}${typeof q.sourceDiscrepancy==='string'?`<p class="notice warning">${esc(q.sourceDiscrepancy)}</p>`:''}${q.annulmentReason?`<p class="notice">Motivo indicado: ${esc(q.annulmentReason)}</p>`:''}${reviewed?`<section class="editorial-reasoning"><h3>Entender la pregunta</h3>${paragraph(q.explanation)}<details class="sources teaching-sources"><summary>Referencias de esta ampliación · ${esc(q.teachingReview.date)}</summary><p class="small muted">${esc(q.teachingReview.method)}</p>${externalRefs(q.teachingReview.sources)}</details></section>`:''}${errorChoice(attemptId)}${imageGuide(q)}${clinicalUpdate(q)}<h3>Opción por opción</h3>${options}${shared}${pending}${recallCard(q)}${source}${q.commentaryImages?.length?`<details class="commentary"><summary>Imágenes de la explicación</summary>${figures({...q,images:q.commentaryImages})}</details>`:''}${q.elaboration?`<details class="commentary"><summary>Elaboración didáctica adicional</summary>${paragraph(q.elaboration)}</details>`:''}${refs(q)}${relatedVersions(q)}</section>`;
}
function learningContent(q){if(!q)return q;const current=lookup(q.id);if(!current||current.stem!==q.stem||JSON.stringify(current.options)!==JSON.stringify(q.options)||current.answer!==q.answer)return q;return {...q,...Object.fromEntries(['memory','takeaway','optionExplanations','clinicalUpdate','learningConcept','explanation','optionTeaching','teachingReview','imageTeaching','externalClinicalReview','images','image','imageRecovery','imageRequired','flags','status','eligible','references','imageRequirementReview'].filter(k=>current[k]!=null).map(k=>[k,current[k]]))};}
function ampliaciones(){const list=bank.questions.filter(q=>q.teachingReview&&q.explanation&&q.options.every((_,i)=>C.optionReason(q,i).kind==='authored')).sort((a,b)=>String(b.teachingReview.date).localeCompare(String(a.teachingReview.date)));shell('Explicaciones ampliadas',`<section class="card"><h2>${list.length} preguntas con ampliación por opción</h2><p>Razonamiento del caso, comparación de alternativas y una frase para recordar. Las fichas con imagen incluyen dónde mirar y qué aporta el hallazgo. Cada ampliación identifica las referencias consultadas y su fecha.</p><p class="small muted">Esta selección tiene contenido didáctico elaborado por IA con consulta de fuentes; no cuenta con revisión clínica externa. La revisión del resto del banco sigue incompleta.</p></section>${list.map(q=>`<article class="card bank-row"><div class="row-meta">${badge(q.subject||'')}${badge(q.year?'Fuente · '+q.year:'Fuente documental')}${badge(q.teachingReview.date)}</div><h3>${esc(q.stem)}</h3>${button('open-question','Responder y estudiar','primary',`data-id="${esc(q.id)}"`)}</article>`).join('')||'<p class="notice">Esta copia todavía no incluye ampliaciones con este formato.</p>'}`);}
function guidelineActivity(){const learning=bank.manifest.learning||{},events=learning.guidelineEvents||[];return `${learning.guidelineMonitoring?.enabled?'<p>Comprobación semanal activada para '+esc(learning.guidelineRegister?.length||0)+' referencias enlazadas. Los cambios relevantes requieren contraste clínico.</p>':''}${learning.guidelineLastCheck?.at?'<p class="small muted">Última comprobación: '+esc(learning.guidelineLastCheck.at)+'</p>':''}${events.length?events.slice(-30).reverse().map(e=>`<article class="note"><strong>${esc(e.title||e.summary||'Cambio de referencia')}</strong><p>${esc(e.date||e.at||'')} · Pendiente de revisión clínica</p>${e.summary&&e.title?'<p>'+esc(e.summary)+'</p>':''}${e.url&&/^https:\/\//.test(e.url)?'<a target="_blank" rel="noopener noreferrer" href="'+esc(e.url)+'">Consultar la fuente</a>':''}</article>`).join(''):'<p class="small muted">Todavía no hay cambios clínicos registrados en esta cola.</p>'}`;}
function completionActivity(){const a=bank.manifest.learning?.automaticCompletion;if(!a)return '';const batch=a.lastBatch||{};return `<section class="card"><h2>Ampliación automática del banco</h2><p>${a.enabled?'Continuación programada por lotes cada hora.':'Continuación automática pausada.'} Cada pregunta conserva su versión y sus fuentes.</p><p>${esc(a.completedSinceStart||0)} explicaciones completadas desde el inicio de esta ampliación · ${esc(a.pendingExplanations??'—')} pendientes.</p>${batch.questionIds?.length?`<details><summary>Últimas ${batch.questionIds.length} preguntas ampliadas · ${esc(batch.date||'')}</summary>${batch.questionIds.map(id=>lookup(id)).filter(Boolean).map(q=>`<p>${button('open-question',esc(q.stem.slice(0,130)),'ghost',`data-id="${esc(q.id)}"`)}</p>`).join('')}</details>`:''}<p class="small muted">La programación permite continuar el trabajo; no certifica cuándo terminará. La revisión clínica externa requiere un profesional independiente.</p></section>`;}
function quality(){const c=L.coverage(bank),sources=bank.manifest.learning?.guidelineRegister||[];shell('Revisión y fuentes',`${completionActivity()}<section class="card"><h2>Qué está revisado</h2><p>${c.total} preguntas inventariadas · ${c.authored} con explicación propia de todas sus opciones · ${c.structured} con comparación y trampa por opción.</p><p>${c.total-c.authored} preguntas siguen pendientes de completar sus explicaciones propias. ${c.imagesPending} imágenes necesarias siguen sin localizar.</p><p><strong>${c.external} preguntas con revisión clínica externa registrada para su versión actual.</strong> La elaboración por IA y la consulta de una referencia no cuentan como revisión por un profesional independiente.</p></section><section class="card"><h2>Cambios que afectan al estudio</h2>${guidelineActivity()}<p>Las correcciones conservan el comentario histórico y su procedencia. Las respuestas y la puntuación de sesiones anteriores se mantienen tal como se registraron.</p><p>Las fuentes que cambien pasan a una cola de contraste. Un cambio en una página no se incorpora automáticamente como recomendación clínica.</p></section><section class="card"><h2>Registro de referencias</h2><p class="small muted">Este registro cubre las referencias enlazadas de las ampliaciones. El resto del banco todavía necesita asociarse a guías y revisión clínica. La fecha indica consulta editorial, no certificación de vigencia.</p>${sources.map(r=>`<article class="note"><strong>${esc(r.title)}</strong><p class="small">${r.questionIds?.length||0} preguntas asociadas · ${esc(r.lastEditorialCheck||'Consulta pendiente')}</p>${externalRefs([r])}<p class="small muted">${esc(r.statusLabel||'Contraste de cambios pendiente')}</p></article>`).join('')||'<p>El registro todavía no está incorporado en esta copia.</p>'}</section>`);}
function externalRefs(list){return (list||[]).filter(r=>/^https:\/\//.test(r.url||'')).map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)}</a>`).join(' · ');}
function clinicalUpdate(q){const r=q.clinicalUpdate;return r?`<aside class="notice clinical-update"><h3>Aclaración del contenido · ${esc(r.date)}</h3>${paragraph(r.text)}<p class="small">${externalRefs(r.sources)}</p></aside>`:'';}
function memoryBody(m){return `<p class="memory-phrase" data-learning-concept="${esc(m.concept||'')}">${esc(m.mnemonic)}</p><div class="memory-map" role="group" aria-label="Esquema para recordar">${(m.visual||[]).map(([a,b])=>`<div><strong>${esc(a)}</strong><span>${esc(b)}</span></div>`).join('')}</div><p><strong>Dato que decide:</strong> ${esc(m.clue)}</p><p class="memory-trap"><strong>Evita la trampa:</strong> ${esc(m.trap)}</p>${m.webReferences?.length?`<details class="sources"><summary>Fuentes de la ampliación</summary>${externalRefs(m.webReferences)}</details>`:''}`;}
function recallCard(q){const r=C.recall(q),m=q.memory;return `<div class="recall-prompt"><h3>Para recordarlo</h3>${r.warnings.map(t=>`<p class="small notice warning">${esc(t)}</p>`).join('')}${m&&!q.sourceDiscrepancy&&!q.isAnnulled&&!q.isChallenged?memoryBody(m):r.idea?paragraph(r.idea):`${r.key?`<p><strong>${esc(r.keyLabel)}:</strong> ${esc(r.key)}</p>`:''}${r.excerpts.length?`<div class="recall-excerpts">${r.excerpts.map(t=>`<p>${esc(t)}</p>`).join('')}</div><p class="small muted">Recordatorio extraído de ${esc(r.source.title)}${r.source.pdfPage?' · p. '+esc(r.source.pdfPage):''}. Numeración de opciones del documento original.</p>`:''}`}${m?.concept?button('concept-practice','Aplicarlo en otro caso','ghost',`data-key="${esc(m.concept)}" data-assisted="true"`):''}</div>`;}
function memories(){shell('Frases y casos',`<p>Elige primero «Comprobar recuerdo» si quieres practicar sin ver la pista. Los casos son ejercicios didácticos originales.</p>${(bank.flashcards||[]).filter(c=>c.memoryCard).map(m=>`<section class="card"><h2>${esc(m.front)}</h2>${button('concept-practice','Comprobar recuerdo','primary',`data-key="${esc(m.concept)}"`)}<details class="memory-details" data-concept="${esc(m.concept)}"><summary>Ver frase y esquema</summary>${memoryBody(m)}${refs(m)}</details></section>`).join('')}`);main.querySelectorAll('.memory-details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open){const b=d.parentElement.querySelector('[data-action="concept-practice"]');b.dataset.assisted='true';b.textContent='Practicar con la pista';}}));}
function dailyMemory(date){const m=C.memoryOfDay(bank,state,date);if(m&&L.queue(bank,state).some(x=>x.key===m.concept&&x.dueAt<=Date.now()))return ''; return m?`<section class="card daily-memory"><p class="eyebrow">UNA IDEA PARA LLEVARTE AL EXAMEN</p><h2>${esc(m.front)}</h2>${memoryBody(m)}<div class="toolbar">${button('concept-practice','Practicar otro caso','primary',`data-key="${esc(m.concept)}" data-assisted="true"`)}${button('reading','Entenderlo a fondo','ghost',`data-id="read-${esc(m.concept)}"`)}${button('navigate','Todas las frases','ghost','data-view="memories"')}</div><p class="small muted">Con la pista recién vista, la práctica se registra como estudio con ayuda. Tus diez preguntas diarias siguen aparte.</p>${refs(m)}</section>`:'';}
function conceptPanel(){const groups=C.conceptProgress(bank,state),labels={reforzar:'Para reforzar',con_dudas:'Acierto con dudas',comprobar:'Por comprobar con tiempo',retenido:'Recordado con separación'};return `<section class="card concept-progress"><h2>Lo que recuerdas con el tiempo</h2><p class="small muted">«Recordado con separación» exige aciertos seguros, sin ayuda, en al menos dos preguntas distintas y en dos días separados por siete días o más. Un error reciente vuelve a poner el concepto en repaso. Es una regla de seguimiento, no una garantía de dominio.</p>${groups.length?groups.slice(0,30).map(g=>`<div class="concept-row"><div><strong>${esc(g.label)}</strong><p class="small">${esc(g.subject)} · ${g.distinctQuestions} preguntas distintas · ${g.days} días de práctica</p>${badge(labels[g.status],g.status==='retenido'?'good':'')}</div>${button('concept-practice','Comprobar recuerdo','ghost',`data-key="${esc(g.key)}"`)}</div>`).join(''):'<p>Se completará con tus respuestas sin ayuda. Leer una frase o acertar justo después de verla no se considera recuerdo duradero.</p>'}</section>`;}


function errorChoice(id){const a=state.attempts.find(x=>x.id===id);if(!a||a.kind!=='question'||a.scored===false||a.correct!==false)return'';const cause=state.errorReviews?.[id]?.cause;return `<aside class="error-choice notice"><h3>¿Qué te hizo fallar?</h3><p class="small">Elige el motivo principal. Puedes cambiarlo; no afecta a tu puntuación.</p><div class="toolbar">${Object.entries(L.CAUSES).map(([key,c])=>button('error-cause',esc(c.label),cause===key?'primary':'ghost',`data-attempt="${esc(id)}" data-cause="${key}" aria-pressed="${cause===key}"`)).join('')}</div><p class="small error-advice">${cause?esc(L.CAUSES[cause].advice):'Sin clasificar hasta que tú lo indiques.'}</p></aside>`;}
function errorPanel(){const p=L.errorProfile(state);return `<section class="card error-profile"><h2>Por qué fallas</h2><p>${p.total} intentos fallados · ${p.unknown} sin clasificar. El motivo lo indicas tú al revisar cada respuesta.</p><div class="cards-grid">${Object.entries(L.CAUSES).map(([key,c])=>`<div><h3>${p.counts[key]} · ${esc(c.label)}</h3><p class="small">${esc(c.advice)}</p>${button('errors-by-cause','Repasar errores de este tipo','ghost',`data-cause="${key}" ${p.counts[key]?'':'disabled'}`)}</div>`).join('')}</div></section>`;}
function delayedPanel(compact=false){const queue=L.queue(bank,state),ready=queue.filter(x=>x.ready),recent=queue.filter(x=>x.lastCheck).sort((a,b)=>b.lastCheck.at-a.lastCheck.at).slice(0,5);if(compact&&!ready.length)return'';return `<section class="card delayed-recall"><p class="eyebrow">RECUERDO A 7 Y 30 DÍAS</p><h2>${ready.length?ready.length+' conceptos listos para comprobar':'Dejar pasar tiempo también forma parte del estudio'}</h2><p>Responde un caso distinto, sin ver antes la frase ni la solución. Tras una primera comprobación segura a los 7 días, el siguiente objetivo es 30 días desde el último estudio. Si repasas antes, el intervalo empieza de nuevo.</p>${button('delayed-start','Comprobar con casos nuevos','primary',ready.length?'':'disabled')}${!compact?`<p class="small muted">Solo se agrupan conceptos identificados de forma específica. Los casos ya vistos y las preguntas con incidencias se excluyen. Esta comprobación describe tus respuestas, no garantiza dominio clínico.</p>${queue.slice(0,15).map(x=>`<div class="history-row"><div><strong>${esc(x.label)}</strong><p class="small">${esc(x.subject||'')} · objetivo ${x.stageDays} días</p></div><span>${x.ready?'Listo sin pista':x.blocked==='cases'?'Hace falta otro caso de este concepto':x.blocked==='session'?'Hay una sesión en curso':new Date(x.dueAt).toLocaleDateString('es-ES',{timeZone:state.preferences.timezone})}</span></div>`).join('')||'<p>Se programará al estudiar conceptos que tengan otros casos disponibles.</p>'}${recent.length?'<h3>Últimas comprobaciones</h3>'+recent.map(x=>`<p>${esc(x.label)} · ${x.lastCheck.stageDays} días · ${x.lastCheck.correct?(x.lastCheck.confidence==='sure'?'recordado sin pista':'acierto con dudas'):'para reforzar'}</p>`).join(''):''}`:''}</section>`;}
function imageGuide(q){const t=q.imageTeaching;return t&&q.images?.length?`<section class="notice image-teaching"><h3>Leer esta imagen</h3><p><strong>Dónde mirar:</strong> ${esc(t.lookAt)}</p><p><strong>Hallazgo que decide:</strong> ${esc(t.decisiveFinding)}</p><p><strong>No confundir:</strong> ${esc(t.pitfall)}</p><p class="small muted">${esc(t.method||'Orientación didáctica; revisión clínica externa pendiente.')}</p></section>`:'';}
function recordVisibleLearning(){if(!state)return;let changed=false;main.querySelectorAll('[data-learning-concept]').forEach(el=>{const key=el.dataset.learningConcept;if(!key)return;for(let p=el.parentElement;p&&p!==main;p=p.parentElement)if(p.tagName==='DETAILS'&&!p.open)return;const now=Date.now();if(now-(state.conceptExposures?.[key]?.at||0)>1000){L.expose(state,key,'contenido visible',now);changed=true;}});if(changed)save();}
main.addEventListener('toggle',recordVisibleLearning,true);

function questionIssues(q){return C.observations(q).map(x=>x.label);}
function observationNotice(q,scored=C.eligible(q)){const issues=questionIssues(q);if(!issues.length)return !scored&&C.eligible(q)?'<aside class="notice observation-notice">El contenido de esta pregunta se ha completado desde que se creó la sesión. Este intento conserva su condición original sin puntuación.</aside>':'';return `<aside class="notice warning observation-notice"><strong>Pregunta con observaciones · ${scored?'puntuable':'sin puntuación'}</strong><ul>${issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="small">Puedes responder y estudiar su explicación. ${scored?'':'Este intento se conserva como estudio y no modifica tu porcentaje de aciertos.'}</p></aside>`;}
function relatedVersions(q){const related=[q.duplicateOf,...(q.equivalentIds||[])].filter(id=>id&&lookup(id));return related.length?`<details class="related-versions"><summary>Versiones documentales vinculadas (${related.length})</summary><p class="small">Se conserva cada versión con sus fuentes. Los bloques automáticos evitan repetir la misma pregunta.</p>${related.map(id=>button('open-question','Estudiar '+esc(lookup(id).origin||lookup(id).id),'ghost',`data-id="${esc(id)}"`)).join('')}</details>`:'';}
function figures(q){const ids=q.images||[];return`<div class="question-images">${ids.map(id=>`<figure><button class="image-button" data-action="zoom" data-id="${esc(id)}"><img data-media="${esc(id)}" alt="Imagen del documento, ampliar" loading="lazy"></button><figcaption>Imagen del material aportado · pulsa para ampliar</figcaption></figure>`).join('')}${q.imageRequired&&!ids.length&&!q.image?'<p class="notice image-missing">Imagen necesaria no localizada. Puedes estudiar el enunciado y los comentarios; esta pregunta no puntúa.</p>':''}${!ids.length&&q.image&&/^data:image\/(png|jpeg|webp);base64,/.test(q.image)?`<img class="source-image" src="${esc(q.image)}" alt="Imagen del material aportado">`:''}</div>`;}
const imageObserver='IntersectionObserver'in window?new IntersectionObserver(es=>{for(const e of es)if(e.isIntersecting){imageObserver.unobserve(e.target);fillImage(e.target);}}, {rootMargin:'250px'}):null;
function observeImage(el){if(imageObserver)imageObserver.observe(el);else fillImage(el);}
async function fillImage(el){try{const m=await S.media(el.dataset.media);if(!el.isConnected)return;if(m?.data&&/^data:image\/(png|jpeg|webp);base64,/.test(m.data)){el.src=m.data;el.alt=m.alt||'Imagen del documento';}else{el.alt='Imagen no disponible: el banco privado aún no ha incorporado este recurso.';el.classList.add('image-error');}}catch{el.alt='No se pudo cargar la imagen. Reintenta cuando haya conexión.';el.classList.add('image-error');}}
async function zoom(id){const m=await S.media(id);if(!m?.data)return toast('Esta imagen no está incorporada en el banco de este dispositivo.');showDialog('Imagen del documento',`<label>Ampliación<input id="image-zoom" aria-label="Ampliación de la imagen" type="range" min="100" max="300" step="25" value="100"></label><div class="zoom-viewport"><img class="zoom-image" src="${esc(m.data)}" alt="${esc(m.alt||'Imagen de la fuente')}"></div><p class="muted small">${esc(m.alt||'')} · Usa el deslizador y desplázate por la imagen ampliada.</p>`);$('#image-zoom').oninput=e=>{$('#dialog .zoom-image').style.width=e.target.value+'%';};}
function showDialog(title,body){const d=$('#dialog');d.innerHTML=`<div class="dialog-top"><h2>${esc(title)}</h2><button data-action="close-dialog" aria-label="Cerrar">×</button></div>${body}`;d.showModal();}
function start(items,options={}){if(!items.length)return toast('No hay preguntas válidas para este filtro.');const s=C.makeSession(bank,state,items,options);state.sessions[s.id]=s;state.activeSession=s.id;currentSession=s.id;save();go('session');}
function today(){const key=C.dayKey(new Date(),state.preferences.timezone),existing=state.sessions['daily-'+key],last=state.sessions[state.activeSession],n=bank.questions.filter(C.studyable).length,st=C.stats(state,bank);shell('Hoy',`<section class="hero"><div><p class="eyebrow">POCO CADA DÍA, BIEN APRENDIDO</p><h2>${existing?.status==='complete'?'Tu sesión de hoy está completada':state.preferences.dailySize+' '+(state.preferences.dailyMode==='questions'?'preguntas':'actividades')+'. Un paso real.'}</h2><p>Responde, entiende el dato que decide y vuelve a recordarlo con el tiempo.</p><div class="toolbar">${S.offline&&bank.manifest.offlineSession?button('open-session','Continuar sesión descargada','primary',`data-id="${esc(bank.manifest.offlineSession)}"`):button('daily',existing?existing.status==='complete'?'Revisar la sesión':'Continuar mi sesión':'Empezar mi sesión','primary')}${last&&last.id!==existing?.id&&last.status==='active'?button('resume','Retomar bloque pendiente','light'):''}</div></div><div class="hero-number">${state.preferences.dailySize}<span>${state.preferences.dailyMode==='questions'?'preguntas de hoy':'actividades de hoy'}</span></div></section>${delayedPanel(true)}${dailyMemory(key)}<div class="metrics"><div class="card"><strong class="metric">${n.toLocaleString('es-ES')}</strong><span>preguntas disponibles para estudiar</span></div><div class="card"><strong class="metric">${st.unresolved}</strong><span>preguntas con último intento fallado</span></div><div class="card"><strong class="metric">${st.first.percent==null?'—':st.first.percent+'%'}</strong><span>aciertos en primer intento</span></div></div><div class="two-columns"><section class="card"><h2>Tu rutina</h2><p>Elige el formato. Los bloques extra son voluntarios.</p><label>Sesión diaria<select id="daily-mode"><option value="mixed" ${state.preferences.dailyMode==='mixed'?'selected':''}>Preguntas + tarjetas + lecturas</option><option value="questions" ${state.preferences.dailyMode==='questions'?'selected':''}>Solo preguntas</option></select></label><label class="spaced">Tamaño de la sesión<select id="daily-size">${[5,10,15,20,25,50].map(n=>`<option value="${n}" ${state.preferences.dailySize===n?'selected':''}>${n} actividades</option>`).join('')}</select></label><label class="check spaced"><input id="include-observations" type="checkbox" ${state.preferences.includeObservations?'checked':''}>Incluir preguntas con observaciones en mis sesiones</label><p class="small muted">Conservan su aviso y no alteran los aciertos. El cambio se aplica a sesiones nuevas.</p><div class="toolbar spaced">${button('extra','+5 preguntas','ghost','data-count="5"')}${button('extra','+10','ghost','data-count="10"')}${button('extra','+25','ghost','data-count="25"')}</div><p class="small muted">La selección adaptativa es una regla de estudio, no un algoritmo validado para predecir tu puesto MIR.</p></section><section class="card"><h2>Contenido con procedencia</h2><p><b>${bank.readings.length}</b> lecturas · <b>${bank.flashcards.length}</b> tarjetas · ${bank.manifest.images?`<b>${bank.manifest.images}</b> imágenes incorporadas · `:''}<b>${C.uniqueQuestions(bank.questions.filter(x=>!x.duplicateOf&&x.images?.length)).length}</b> fichas visuales vinculadas.</p><p>Todas las preguntas pueden estudiarse. Las anuladas, discrepantes o incompletas se identifican y no alteran tus aciertos.</p>${button('navigate','Explorar el banco','primary','data-view="bank"')}</section></div>${S.offline?'<p class="notice">Estás usando la sesión descargada. Los avances se guardan en este dispositivo y se sincronizarán cuando vuelvas a tener conexión.</p>':''}${S.local?'<p class="notice">Modo local: el banco está incluido en este archivo y el progreso se guarda en este navegador. No se sincroniza con otros dispositivos hasta conectar la copia privada con la web.</p>':''}`);$('#include-observations').onchange=e=>{state.preferences.includeObservations=e.target.checked;save();toast('Preferencia guardada para las sesiones nuevas.');};$('#daily-size').onchange=e=>{state.preferences.dailySize=+e.target.value;save();today();toast('El nuevo tamaño se aplicará a la próxima sesión diaria.');};$('#daily-mode').onchange=e=>{state.preferences.dailyMode=e.target.value;save();today();toast('Preferencia guardada; una sesión ya iniciada no se modifica.');};}
function daily(){const key=C.dayKey(new Date(),state.preferences.timezone),id='daily-'+key;let s=state.sessions[id];if(!s){const items=C.selectDaily(bank,state,key,state.preferences.dailySize);if(!items.length)return toast('El banco no tiene actividades disponibles.');s=C.makeSession(bank,state,items,{id,kind:'daily',title:'Mi sesión · '+key});state.sessions[id]=s;}if(s.status==='complete')s.index=0;else state.activeSession=id;currentSession=id;save();go('session');}
function selectItems(list,count=10){return C.shuffled(C.uniqueQuestions(list.filter(C.studyable).sort((a,b)=>Number(!C.eligible(a))-Number(!C.eligible(b))||Number(!!a.duplicateOf)-Number(!!b.duplicateOf))),Date.now()).slice(0,count).map(q=>({id:q.id,kind:'question'}));}
function bankView(){const subjects=[...new Set(bank.questions.map(x=>x.subject||'Sin clasificar'))].sort(),years=[...new Set(bank.questions.map(x=>x.year).filter(Boolean))].sort((a,b)=>b-a);shell('Banco de preguntas',`<section class="card filters"><label class="wide">Buscar en enunciados, temas y comentarios<input id="bank-search" type="search" placeholder="Ej.: disnea, sensibilidad, insuficiencia cardiaca…" value="${esc(filters.text)}"></label><label>Asignatura<select id="filter-subject"><option value="">Todas</option>${subjects.map(x=>`<option value="${esc(x)}" ${filters.subject===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Año según fuente<select id="filter-year"><option value="">Todos</option>${years.map(x=>`<option ${String(x)===filters.year?'selected':''}>${x}</option>`).join('')}</select></label><label>Estado<select id="filter-status"><option value="eligible" ${filters.status==='eligible'?'selected':''}>Sin incidencias</option><option value="pending" ${filters.status==='pending'?'selected':''}>Con observaciones</option><option value="all" ${filters.status==='all'?'selected':''}>Todas</option></select></label><label class="check"><input id="filter-images" type="checkbox" ${filters.images?'checked':''}>Con imagen incorporada</label><label class="check"><input id="filter-favorites" type="checkbox" ${filters.favorites?'checked':''}>Mis favoritas</label></section><div id="bank-results"></div>`,'Busca el contenido, no solo el título del PDF.');$('#bank-search').oninput=e=>{filters.text=e.target.value;filters.page=0;clearTimeout(bankView.timer);bankView.timer=setTimeout(bankResults,140);};for(const [id,key] of [['filter-subject','subject'],['filter-year','year'],['filter-status','status'],['filter-images','images'],['filter-favorites','favorites']])$('#'+id).onchange=e=>{filters[key]=e.target.type==='checkbox'?e.target.checked:e.target.value;filters.page=0;bankResults();};bankResults();}
function filteredQuestions(){const text=tidy(filters.text);return bank.questions.filter(q=>(filters.status==='all'||(filters.status==='eligible'?!C.hasObservations(q):C.hasObservations(q)))&&(!filters.subject||q.subject===filters.subject)&&(!filters.year||String(q.year)===filters.year)&&(!filters.images||q.images?.length||q.image)&&(!filters.favorites||C.markFor(q,state)?.value)&&(!text||tidy(q.stem+' '+q.subject+' '+q.topic+' '+(q.commentary||'')+' '+(q.sourceCommentaries||[]).map(c=>c.text).join(' ')).includes(text)));}
function bankResults(){const list=filteredQuestions(),pages=Math.max(1,Math.ceil(list.length/20));filters.page=Math.max(0,Math.min(filters.page,pages-1));$('#bank-results').innerHTML=`<div class="results-bar"><p><strong>${list.length.toLocaleString('es-ES')}</strong> preguntas encontradas</p>${button('practice-filter','Practicar hasta 10','primary')}${button('print-filter','Imprimir selección (hasta 25)')}</div>${list.slice(filters.page*20,filters.page*20+20).map(q=>`<article class="card bank-row"><div class="row-meta">${badge(q.subject||'Sin clasificar')}${badge(q.year?'MIR según fuente · '+q.year:'Original')}${badge(statusText(q),C.eligible(q)?'':'warn')}${q.images?.length?badge('Con imagen'):''}</div><h3>${esc(q.stem)}</h3><p class="muted small">${esc(q.topic||'')} · ${q.references?.length||0} referencia(s)</p><div class="toolbar">${button('open-question','Responder y estudiar','primary',`data-id="${esc(q.id)}"`)}${button('favorite',C.markFor(q,state)?.value?'★ Guardada':'☆ Guardar','ghost',`data-id="${esc(q.id)}"`)}</div></article>`).join('')||'<div class="empty">No hay resultados con estos filtros.</div>'}<div class="toolbar pagination">${button('bank-page','Anterior','ghost',`data-page="${filters.page-1}" ${filters.page===0?'disabled':''}`)}<span>Página ${filters.page+1} de ${pages}</span>${button('bank-page','Siguiente','ghost',`data-page="${filters.page+1}" ${filters.page+1>=pages?'disabled':''}`)}</div>`;}
function openQuestion(id){const q=lookup(id);if(!q)return toast('No se encuentra la pregunta.');start([{id:q.id,kind:'question'}],{title:C.eligible(q)?'Práctica de una pregunta':'Estudio con observaciones'});}
function sessionView(){const s=state.sessions[currentSession||state.activeSession];if(!s)return go('today');currentSession=s.id;if(s.status==='active'&&s.deadline&&Date.now()>=s.deadline){C.finish(state,s,lookup);save();}if(s.status==='complete'&&s.mode==='exam')return resultView(s);const i=Math.min(s.index||0,s.items.length-1),item=s.items[i],q=learningContent(item?.data||lookup(item?.id));if(!q)return shell('Contenido no disponible','<p class="notice warning">Esta sesión hace referencia a un contenido que no está cargado. El historial no se ha eliminado.</p>');const key=s.id+':'+i;if(key!==enteredKey){enteredKey=key;enteredAt=Date.now();}const scored=C.itemScored(item),a=s.answers[i]||{},exam=s.mode==='exam',finished=s.status==='complete',revealed=(a.submitted&&!exam)||finished;const answered=Object.values(s.answers).filter(x=>x.submitted).length;
let body=`<div class="session-bar"><span>Actividad <strong>${i+1}/${s.items.length}</strong> · ${esc(item.reason||'')}</span>${s.deadline&&s.status!=='complete'?'<strong id="countdown"></strong>':''}${button('session-print','Imprimir')}${!S.local?button('prepare-offline','Descargar esta sesión','ghost',S.offline?'disabled':''):''}${s.status==='complete'&&s.mode!=='exam'?button('session-print-solutions','Imprimir explicaciones'):''}</div><progress max="${s.items.length}" value="${answered}"></progress>`;
if(item.kind==='question')body+=`<article class="card question-card"><div class="row-meta">${badge(q.subject||'Sin clasificar')}${badge(q.year?'Fuente · '+q.year:'Original')}${badge(exam&&!finished?'Examen · soluciones al entregar':statusText(q))}</div><p class="muted small">${esc(q.topic||'')}</p>${observationNotice(q,scored)}${q.context?`<details class="notice" open><summary>Contexto que acompaña a esta pregunta</summary>${paragraph(q.context.stem)}${figures(q.context)}${refs(q.context)}</details>`:''}<h2 class="stem">${esc(q.stem)}</h2>${figures(q)}<div class="options">${(item.order||q.options.map((_,j)=>j)).map((orig,pos)=>`<button class="option ${a.selected===orig?'selected':''} ${revealed&&scored&&orig===q.answer?'correct':''} ${revealed&&scored&&a.selected===orig&&orig!==q.answer?'wrong':''}" data-action="select-option" data-index="${orig}" ${(finished||a.submitted&&!exam)?'disabled':''}><span class="option-number">${pos+1}</span><span>${esc(q.options[orig])}</span></button>`).join('')}</div><div class="toolbar spaced answer-controls"><label>Seguridad<select id="confidence" ${finished||a.submitted&&!exam?'disabled':''}><option value="unsure" ${a.confidence==='unsure'?'selected':''}>Dudaba</option><option value="sure" ${a.confidence==='sure'?'selected':''}>Estaba seguro</option><option value="guess" ${a.confidence==='guess'?'selected':''}>Al azar</option></select></label>${button('answer','Confirmar respuesta','primary',`${finished||a.submitted&&!exam?'disabled':''}`)}${button('blank','Dejar en blanco','ghost',`${finished||a.submitted&&!exam?'disabled':''}`)}</div>${revealed?correction(q,a,scored,s.id+':'+i)+`<p class="small muted">${(scored?state.schedule:state.studySchedule)[q.id]?'Próximo repaso'+(scored?'': ' de estudio')+': '+new Date((scored?state.schedule:state.studySchedule)[q.id].dueAt).toLocaleDateString('es-ES',{timeZone:state.preferences.timezone}):''}</p>`:''}<div class="toolbar spaced">${button('favorite',C.markFor(q,state)?.value?'★ Guardada':'☆ Guardar','ghost',`data-id="${esc(q.id)}"`)}${button('note','Mi nota','ghost',`data-id="${esc(q.id)}"`)}${button('report','Señalar problema','ghost',`data-id="${esc(q.id)}"`)}</div></article>`;
else if(item.kind==='flashcard')body+=`<article class="card"><p class="eyebrow">RECUPERACIÓN SIN OPCIONES</p><h2>${esc(q.front)}</h2><details class="commentary" ${a.submitted||finished?'open':''}><summary>Mostrar respuesta de la tarjeta</summary><div data-learning-concept="${esc(q.concept||'')}">${paragraph(q.back)}</div>${refs(q)}</details><div class="toolbar spaced">${['again','hard','good'].map((rate,j)=>button('rate',['No lo recordaba','Me costó','Lo recordaba'][j],j===2?'primary':'ghost',`data-rating="${rate}" ${a.submitted||finished?'disabled':''}`)).join('')}</div></article>`;
else body+=`<article class="card" data-learning-concept="${esc(q.concept||'')}"><p class="eyebrow">LECTURA DEL MATERIAL APORTADO</p><h2>${esc(q.title)}</h2><p class="notice small">Se conserva el contenido de la fuente, no se presenta como actualización clínica actual.</p>${(q.sections||[]).map(x=>`<section class="reading-section"><h3>${esc(x.title)}</h3>${paragraph(x.text)}</section>`).join('')}${refs(q)}${button('read-done','Lectura realizada','primary',`${a.submitted||finished?'disabled':''}`)}</article>`;
body+=`<div class="session-nav">${button('previous','← Anterior','ghost',i===0?'disabled':'')}${button('next',i===s.items.length-1?(finished?'Volver a Hoy':exam?'Entregar examen':'Terminar sesión'):'Siguiente →','primary')}${!finished&&exam?button('finish-exam','Entregar ahora','ghost'):''}${button('navigate','Pausar y volver a Hoy','ghost','data-view="today"')}</div>${exam&&!finished?`<details class="card"><summary>Navegador del examen · ${answered} confirmadas</summary><div class="question-grid">${s.items.map((_,j)=>`<button class="${s.answers[j]?.submitted?'answered':''} ${j===i?'current':''}" data-action="jump" data-index="${j}">${j+1}</button>`).join('')}</div></details>`:''}`;body+=`<div class="mobile-study-actions" role="group" aria-label="Acciones de la sesión">${button('previous','←','ghost',i===0?'disabled':'')}<span>${i+1}/${s.items.length}</span>${item.kind==='question'&&!revealed&&!exam?button('answer','Confirmar respuesta','primary'):button('next',i===s.items.length-1?'Terminar':'Siguiente →','primary')}</div>`;shell(s.title,body);tick();}
function activeS(){return state.sessions[currentSession||state.activeSession];}
async function submitAnswer(blank=false){const s=activeS();if(!s)return;const i=s.index||0,item=s.items[i];if(s.status==='complete'||item.kind!=='question')return;const selected=blank?null:s.answers[i]?.selected;if(!blank&&selected==null)return toast('Elige una opción o utiliza «Dejar en blanco».');C.answer(state,s,i,{selected,confidence:$('#confidence')?.value||'unsure',seconds:(Date.now()-enteredAt)/1000,retention:L.validateCheck(state,item,Date.now())},lookup);await save();sessionView();}
async function next(){const s=activeS();if(!s)return;const i=s.index||0;if(s.status!=='complete'&&!s.answers[i]?.submitted){if(s.mode==='exam')C.answer(state,s,i,{selected:s.answers[i]?.selected??null,confidence:s.answers[i]?.confidence||'unsure',seconds:(Date.now()-enteredAt)/1000},lookup);else return toast('Registra la respuesta, deja la pregunta en blanco o marca la actividad.');}if(i>=s.items.length-1){if(s.status==='complete')return go('today');if(s.mode==='exam'&&!confirm('¿Entregar el examen? Las preguntas sin confirmar quedarán en blanco.'))return;C.finish(state,s,lookup);await save();if(s.mode==='exam')resultView(s);else{toast('Sesión completada y guardada.');go('today');}}else{s.index=i+1;s.updatedAt=Date.now();await save();sessionView();}}
function resultView(s){const st=C.score(s),unscored=s.items.slice(0,s.mainCount).filter(x=>x.kind==='question'&&!C.itemScored(x)).length;shell('Resultado del simulacro',`<div class="metrics"><div class="card"><strong class="metric">${st.correct}</strong><span>correctas</span></div><div class="card"><strong class="metric">${st.wrong}</strong><span>incorrectas</span></div><div class="card"><strong class="metric">${st.blank}</strong><span>en blanco</span></div></div><section class="card"><h2>${st.net.toFixed(2).replace('.',',')} netas de entrenamiento</h2><p>${st.total} preguntas puntuables · ${unscored} con observaciones sin puntuación.</p><p>Puntuación bruta: ${st.raw} (+3 por acierto, −1 por error). ${s.items.length>s.mainCount?'Las preguntas de reserva se corrigen, pero no se suman sin una sustitución.':''} No estima un puesto ni una nota oficial MIR 2027.</p><div class="toolbar">${button('session-print','Imprimir preguntas')}${button('session-print-solutions','Imprimir corrección')}${button('navigate','Mi progreso','primary','data-view="progress"')}</div></section>${s.items.map((item,i)=>{const q=learningContent(item.data||lookup(item.id)),a=s.answers[i]||{};if(!q||item.kind!=='question')return'';return`<details class="card"><summary><strong>${i+1}. ${!C.itemScored(item)?'Estudio sin puntuación':a.selected==null?'—':a.selected===q.answer?'✓':'✗'} ${esc(q.subject||'')}${i>=s.mainCount?' · reserva':''}</strong></summary><h3>${esc(q.stem)}</h3>${figures(q)}<p>Tu respuesta: ${a.selected==null?'En blanco':esc(q.options[a.selected])}</p>${correction(q,a,C.itemScored(item),s.id+':'+i)}</details>`;}).join('')}`);}
function topics(){const groups={};for(const q of C.selectionPool(bank,state)){const k=q.subject||'Sin clasificar';(groups[k]??=[]).push(q);}shell('Temas y lecturas',`<section class="card"><label>Buscar una lectura o tema<input type="search" id="reading-search" value="${esc(readingFilter)}" placeholder="Busca un tema, asignatura o título"></label><div id="reading-results"></div></section><h2>Practicar por asignatura</h2><div class="cards-grid">${Object.entries(groups).sort((a,b)=>a[0].localeCompare(b[0],'es')).map(([name,items])=>`<section class="card"><h3>${esc(name)}</h3><p>${items.length} preguntas disponibles</p>${button('subject','Practicar hasta 10','primary',`data-subject="${esc(name)}"`)}</section>`).join('')}</div>`,'Lecturas de tus documentos y selección de sus comentarios, con referencias.');$('#reading-search').oninput=e=>{readingFilter=e.target.value;readingPage=0;readingResults();};readingResults();}
function readingResults(){const text=tidy(readingFilter),rs=bank.readings.filter(r=>!text||tidy(r.title+' '+r.subject+' '+r.topic+' '+(r.sections||[]).map(s=>s.text).join(' ')).includes(text));const pages=Math.max(1,Math.ceil(rs.length/40));readingPage=Math.max(0,Math.min(readingPage,pages-1));$('#reading-results').innerHTML=`<p class="small muted">${rs.length} lecturas · página ${readingPage+1} de ${pages}.</p><div class="reading-list">${rs.slice(readingPage*40,readingPage*40+40).map(r=>`<button class="reading-link" data-action="reading" data-id="${esc(r.id)}"><strong>${esc(r.title)}</strong><span>${esc(r.subject||'')} · ${r.minutes||'—'} min orientativos</span></button>`).join('')}</div><div class="toolbar pagination">${button('reading-page','Lecturas anteriores','ghost',`data-page="${readingPage-1}" ${readingPage===0?'disabled':''}`)}${button('reading-page','Más lecturas','ghost',`data-page="${readingPage+1}" ${readingPage+1>=pages?'disabled':''}`)}</div>`;}
function review(){const last=C.latest(state,bank),errors=bank.questions.filter(q=>C.eligible(q)&&last.get(q.id)?.correct===false),due=bank.questions.filter(q=>C.eligible(q)&&C.scheduleFor(q,state)?.dueAt<=Date.now()),fav=bank.questions.filter(q=>C.studyable(q)&&C.markFor(q,state)?.value),st=C.stats(state,bank);shell('Mi repaso',`${delayedPanel()}${errorPanel()}<div class="cards-grid"><section class="card"><h2>${errors.length} errores pendientes</h2><p>Solo se mantiene el último intento de cada pregunta. Un error ya corregido no sigue apareciendo como pendiente.</p>${button('review-errors','Repasar hasta 10','primary',errors.length?'':'disabled')}</section><section class="card"><h2>${due.length} repasos vencidos</h2><p>Intervalos adaptados a la respuesta y a tu seguridad; son reglas de estudio transparentes.</p>${button('review-due','Repasar hasta 10','primary',due.length?'':'disabled')}</section><section class="card"><h2>${fav.length} favoritas</h2><p>Tu selección personal, independiente de la frecuencia histórica del examen.</p>${button('review-favorites','Practicar favoritas','primary',fav.length?'':'disabled')}</section></div><section class="card"><h2>${st.confidentErrors} errores con alta seguridad</h2><p>Estos errores reciben prioridad: conviene revisar el razonamiento, no memorizar la posición de la opción.</p></section><section class="card"><h2>Estudio con observaciones</h2><p>${st.observations} intentos guardados por separado. Se proponen para volver a leer a los siete días, sin clasificarlos como errores.</p>${button('review-study','Repasar observaciones pendientes','primary',Object.values(state.studySchedule).some(p=>p.dueAt<=Date.now())?'':'disabled')}</section><section class="card"><h2>Próximos repasos</h2>${Object.entries(state.schedule).filter(([id,p])=>lookup(id)&&p.dueAt>Date.now()).sort((a,b)=>a[1].dueAt-b[1].dueAt).slice(0,10).map(([id,p])=>`<div class="history-row"><span>${esc(lookup(id).subject||lookup(id).title||'Actividad')}</span><span>${new Date(p.dueAt).toLocaleDateString('es-ES',{timeZone:state.preferences.timezone})}</span></div>`).join('')||'<p>Aparecerán después de estudiar.</p>'}</section><section class="card"><h2>Mis notas</h2>${Object.entries(state.notes).filter(([,n])=>typeof n==='string'?n:n?.text).slice(0,50).map(([id,n])=>`<article class="note"><strong>${esc(lookup(id)?.subject||'Nota')}</strong><p>${esc(typeof n==='string'?n:n.text)}</p>${button('open-question','Abrir pregunta','ghost',`data-id="${esc(id)}"`)}</article>`).join('')||'<p class="muted">Guarda una nota desde cualquier pregunta.</p>'}</section>`);}
async function atlas(){
 const request=++atlasRequest,mode=S.offline?'offline':S.local?'local':'cloud';if(atlasMode!==mode){atlasMetadata=null;atlasMode=mode;}
 if(!atlasMetadata){shell('Atlas visual','<p class="notice">Cargando el catálogo de imágenes…</p>');try{const catalog=await S.mediaCatalog();if(request!==atlasRequest||route()!=='atlas')return;atlasMetadata=catalog;}catch(e){if(request===atlasRequest&&route()==='atlas')shell('Atlas visual',`<p class="notice warning">${esc(e.message)}</p>${button('navigate','Volver a cargar','primary','data-view="atlas"')}`);return;}}
 if(request!==atlasRequest||route()!=='atlas')return;
 const links=new Map();
 for(const q of bank.questions)for(const [kind,ids] of [['question',q.images||[]],['question',q.context?.images||[]],['commentary',q.commentaryImages||[]]])for(const id of ids){const items=links.get(id)||[];if(!items.some(x=>x.q.id===q.id&&x.kind===kind))items.push({q,kind});links.set(id,items);}
 const sourceNames=new Map(bank.sources.map(s=>[s.id,s.title]));
 const list=atlasMetadata.map(m=>{const related=(links.get(m.id)||[]).sort((a,b)=>Number(!!a.q.duplicateOf)-Number(!!b.q.duplicateOf));return {...m,related,kind:related.some(x=>x.kind==='question')?'question':related.some(x=>x.kind==='commentary')?'commentary':'other'};}).filter(m=>(atlasScope==='all'||m.kind===atlasScope)&&(!atlasSearch||tidy([m.title,m.alt,sourceNames.get(m.sourceId),...m.related.map(x=>x.q.subject+' '+x.q.stem)].join(' ')).includes(tidy(atlasSearch))));
 const pages=Math.max(1,Math.ceil(list.length/12));atlasPage=Math.max(0,Math.min(atlasPage,pages-1));
 shell('Atlas visual',`<section class="card filters"><label class="wide">Buscar imágenes<input id="atlas-search" type="search" value="${esc(atlasSearch)}" placeholder="Asignatura, documento o pregunta"></label><label>Mostrar<select id="atlas-scope">${[['all','Todas las imágenes'],['question','Imágenes de preguntas'],['commentary','Imágenes de explicaciones'],['other','Otros recursos conservados']].map(([v,t])=>`<option value="${v}" ${atlasScope===v?'selected':''}>${t}</option>`).join('')}</select></label></section><p class="notice">${S.offline?'Se muestran las imágenes de tu sesión descargada.':'Catálogo completo de imágenes incorporadas.'} Las imágenes de explicaciones pueden contener soluciones. En tus sesiones se muestran después de responder.</p><p><strong>${list.length}</strong> de ${atlasMetadata.length} imágenes · página ${atlasPage+1} de ${pages}</p><div class="cards-grid">${list.slice(atlasPage*12,atlasPage*12+12).map(m=>`<article class="card atlas-image"><div class="row-meta">${badge(m.kind==='question'?'Imagen de pregunta':m.kind==='commentary'?'Imagen de explicación':'Recurso conservado')}</div><h3>${esc(m.related[0]?.q.subject||sourceNames.get(m.sourceId)||'Imagen del documento')}</h3>${figures({images:[m.id]})}<p class="small muted">${esc(sourceNames.get(m.sourceId)||m.title)}${m.pdfPage?' · PDF p. '+esc(m.pdfPage):''}</p>${m.related.length?button('open-question','Estudiar su pregunta','primary',`data-id="${esc(m.related[0].q.id)}"`):'<p class="small muted">Recurso disponible para consulta; vinculación a una pregunta pendiente.</p>'}</article>`).join('')||'<p>No hay imágenes con estos filtros.</p>'}</div><div class="toolbar pagination">${button('atlas-page','Anterior','ghost',`data-page="${atlasPage-1}" ${atlasPage===0?'disabled':''}`)}<span>${atlasPage+1} / ${pages}</span>${button('atlas-page','Siguiente','ghost',`data-page="${atlasPage+1}" ${atlasPage+1>=pages?'disabled':''}`)}</div>`);
 $('#atlas-scope').onchange=e=>{atlasScope=e.target.value;atlasPage=0;atlas();};$('#atlas-search').oninput=e=>{atlasSearch=e.target.value;atlasPage=0;clearTimeout(atlas.timer);atlas.timer=setTimeout(atlas,180);};
}
function exams(){const n=C.uniqueQuestions(C.selectionPool(bank,state)).length;const history=Object.values(state.sessions).filter(s=>s.mode==='exam').sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));shell('Simulacros',`<section class="card"><h2>Examen cronometrado</h2><p>${state.preferences.includeObservations?'Incluye preguntas con observaciones, identificadas y sin puntuación. ':''}Soluciones ocultas hasta entregar, navegación entre preguntas, respuestas en blanco y guardado al avanzar. El tiempo continúa si cierras el navegador.</p><div class="toolbar">${[25,50,100,210].map(x=>button('exam',x===210?'Largo · 200 + 10':x+' preguntas',x===25?'primary':'ghost',`data-count="${x}" ${n<x?'disabled':''}`)).join('')}</div><p class="muted small">El bloque 200 + 10 es un formato de entrenamiento, no el examen oficial de 2027. No se generan casos clínicos nuevos sin revisión.</p></section><section class="card"><h2>Variantes de cálculo</h2><p>Números regenerados con solución matemática. Se identifican como ejercicios originales y no como preguntas oficiales.</p>${button('numeric','Practicar 5 ejercicios de NNT','primary')}</section><section class="card"><h2>Historial</h2>${history.map(s=>`<div class="history-row"><div><strong>${esc(s.title)}</strong><p class="small muted">${esc(s.date)} · ${s.status==='complete'?'Terminado':'En curso'}</p></div>${button('open-session',s.status==='complete'?'Ver corrección':'Continuar','ghost',`data-id="${esc(s.id)}"`)}</div>`).join('')||'<p>Aún no hay simulacros guardados.</p>'}</section>`);}
function progress(){const st=C.stats(state,bank),firsts=state.attempts.filter(x=>x.kind==='question'&&x.scored!==false&&x.first&&!x.help),sure=firsts.filter(x=>x.confidence==='sure');shell('Mi progreso',`<div class="metrics"><section class="card"><strong class="metric">${st.first.total}</strong><span>primeros intentos sin ayuda</span><b>${st.first.percent??'—'}% aciertos</b></section><section class="card"><strong class="metric">${st.repeat.total}</strong><span>repeticiones</span><b>${st.repeat.percent??'—'}% aciertos</b></section><section class="card"><strong class="metric">${st.completed}</strong><span>sesiones completas</span></section></div>${delayedPanel()}${errorPanel()}<section class="card"><h2>Por asignatura · primeros intentos</h2>${Object.entries(st.subjects).map(([sub,p])=>`<div class="stat-line"><span>${esc(sub)}</span><b>${p.percent}% · ${p.correct}/${p.total}</b><progress value="${p.correct}" max="${p.total}"></progress></div>`).join('')||'<p>Tus resultados aparecerán después de responder.</p>'}</section><div class="two-columns"><section class="card"><h2>Confianza y errores</h2><p>${st.confidentErrors} preguntas con último error de alta seguridad.</p><p>Cuando respondiste «seguro» en un primer intento: <b>${sure.length?Math.round(sure.filter(x=>x.correct).length*100/sure.length)+'%':'—'}</b> de acierto (${sure.length} intentos).</p><p class="muted small">Con pocas respuestas, el porcentaje es inestable. No se convierte en pronóstico de nota MIR.</p></section><section class="card"><h2>Aprendizaje complementario</h2><p>${st.observations} preguntas estudiadas con observaciones · sin efecto en el porcentaje.</p><p>${st.cards} tarjetas registradas · ${st.readings} lecturas registradas.</p>${button('export-progress','Exportar copia de progreso','primary')}</section></div><section class="card"><h2>Sesiones recientes</h2>${Object.values(state.sessions).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0)).slice(0,20).map(s=>`<div class="history-row"><span>${esc(s.title)} · ${s.status==='complete'?'completa':'en curso'}</span>${button('open-session','Abrir','ghost',`data-id="${esc(s.id)}"`)}</div>`).join('')}</section>`);}
function library(){const eligible=bank.questions.filter(C.eligible).length;let sources=bank.sources;const counts=new Map();for(const q of bank.questions)for(const r of q.references||[])counts.set(r.id,(counts.get(r.id)||0)+1);shell('Biblioteca y copias',`<div class="metrics"><section class="card"><strong class="metric">${bank.questions.length.toLocaleString('es-ES')}</strong><span>registros en esta copia</span></section><section class="card"><strong class="metric">${eligible.toLocaleString('es-ES')}</strong><span>preguntas puntuables</span></section><section class="card"><strong class="metric">${bank.questions.length-eligible}</strong><span>disponibles con observaciones · sin puntuación</span></section></div><section class="card"><h2>Tu material, tus datos</h2><p>${S.local?'Esta es la edición local: el banco está incluido, sin cuenta nueva ni servicio de pago. El progreso es local a este navegador.':'Tu banco y tu progreso se guardan de forma privada. Entra con la misma cuenta en otro dispositivo para continuar.'}</p><div class="toolbar">${button('export-progress','Copiar progreso')}${button('import-progress','Recuperar/combinar progreso')}${!S.local?button('backups','Copias recientes del navegador')+button('offline-info','Mi sesión descargada'):''}${S.local?button('bridge','Conectar este banco con mi web','primary'):S.role==='admin'?button('import-file','Importar banco privado','primary'):''}${S.local?button('export-bank','Exportar banco JSON'):''}</div><input id="file-input" type="file" accept=".json,application/json" hidden><p class="muted small">No se usa Google Drive. Una descarga debe guardarse en D: desde el navegador; la web no puede escribir silenciosamente en una unidad de tu ordenador.</p></section><section class="card"><h2>Documentos y cobertura real</h2>${sources.map(s=>`<details class="source-row"><summary><strong>${esc(s.title)}</strong> · ${counts.get(s.id)||0} referencias de preguntas</summary><p>${esc(s.file||s.file_name||'')} · ${s.pages||'—'} páginas en la ficha.</p><p>${esc(s.notes||'')}</p>${s.sha256?`<p class="small muted hash">SHA-256: ${esc(s.sha256)}</p>`:''}</details>`).join('')}</section><section class="card"><h2>Frecuencia observada, no predicción</h2><p>La priorización documental se presenta como recurrencia del corpus. No se inventa una probabilidad de salir en 2027.</p>${(bank.topicStats||[]).slice().sort((a,b)=>b.count-a.count).slice(0,20).map(t=>`<div class="history-row"><span>${esc(t.subject)} · ${esc(t.topic)}</span><b>${t.count} registros · ${t.distinctYears} años</b></div>`).join('')||'<p class="muted">Esta copia todavía no tiene un análisis del corpus completo.</p>'}</section><p class="muted small">Versión ${C.VERSION}. Tu recordatorio diario incluye el enlace de estudio; las preguntas y tu progreso permanecen dentro de tu espacio privado.</p>`);}
function render(){if(S.recovering)return resetPasswordView();if(route()==='recover')return recoveryView();if(!ready)return loginView();applyPrefs();const r=route();if(importPayload&&importNonce)return importView();({today,memories,ampliaciones,quality,bank:bankView,topics,review,atlas,exams,progress,library,session:sessionView}[r]||today)();renderNav();}
function loginView(message=''){$('#save-label').textContent='Acceso privado';renderNav();shell('MIR/27',`<section class="auth-card"><div class="brand-large">MIR<span>/27</span></div><h2>Tu banco privado</h2><p class="small muted">Banco completo · todas las preguntas disponibles para estudiar</p><p>Entra con la cuenta que ya activaste. No hace falta crear otra.</p>${message?`<p class="notice warning">${esc(message)}</p>`:''}<form id="login"><label>Correo<input name="email" type="email" autocomplete="username" required></label><label>Contraseña<input name="password" type="password" autocomplete="current-password" required></label><button class="primary" type="submit">Entrar</button></form><p><a href="#recover">He olvidado mi contraseña</a></p><p class="small muted">Utiliza la misma cuenta en móvil y ordenador para conservar tu progreso.</p></section>`);$('#login').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await S.signIn(e.target.email.value,e.target.password.value);e.target.password.value='';await load();}catch(err){toast(err.message);b.disabled=false;}};}
function recoveryView(message=''){
 $('#save-label').textContent='Recuperar acceso';renderNav();
 shell('Recuperar contraseña',`<section class="auth-card"><h2>Vuelve a tu cuenta</h2><p>Escribe el correo con el que accedes a MIR/27. Te enviaremos un enlace para elegir una nueva contraseña.</p><p>Tu cuenta y tu progreso se conservan.</p><p id="recovery-message" class="notice" role="status" ${message?'':'hidden'}>${esc(message)}</p><form id="recover"><label>Correo<input name="email" type="email" autocomplete="username" required></label><button class="primary" type="submit">Enviar enlace de recuperación</button></form><p><a href="#today">Volver al acceso</a></p></section>`);
 $('#recover').onsubmit=async e=>{
  e.preventDefault();const form=e.target,b=form.querySelector('button'),notice=$('#recovery-message');b.disabled=true;notice.hidden=true;
  try{await S.requestPasswordReset(form.elements.namedItem('email').value);notice.textContent='Si el correo corresponde a tu cuenta, recibirás un enlace para cambiar la contraseña. Revisa también Spam y abre el correo más reciente.';notice.hidden=false;form.hidden=true;}
  catch(err){notice.textContent=err.status===429?'Se han solicitado varios enlaces. Espera unos minutos antes de intentarlo de nuevo.':err.message;notice.hidden=false;b.disabled=false;}
 };
}
function resetPasswordView(){
 $('#save-label').textContent='Elegir nueva contraseña';renderNav();
 shell('Nueva contraseña',`<section class="auth-card"><h2>Elige tu nueva contraseña</h2><p>Utiliza al menos 8 caracteres. Tu progreso seguirá asociado a la misma cuenta.</p><p id="password-message" class="notice warning" role="alert" hidden></p><form id="reset-password"><label>Nueva contraseña<input name="password" type="password" autocomplete="new-password" minlength="8" required></label><label>Repetir contraseña<input name="confirmation" type="password" autocomplete="new-password" minlength="8" required></label><button class="primary" type="submit">Guardar nueva contraseña</button></form><p>Después podrás entrar con la nueva contraseña.</p></section>`);
 $('#reset-password').onsubmit=async e=>{
  e.preventDefault();const form=e.target,password=form.elements.namedItem('password'),confirmation=form.elements.namedItem('confirmation'),b=form.querySelector('button'),notice=$('#password-message');
  if(password.value!==confirmation.value){notice.textContent='Las contraseñas no coinciden.';notice.hidden=false;return;}
  b.disabled=true;notice.hidden=true;
  try{await S.updatePassword(password.value);password.value='';confirmation.value='';await S.signOut();ready=false;bank=null;state=null;index.clear();history.replaceState(null,'','#today');loginView('Contraseña actualizada. Ya puedes entrar con la nueva.');}
  catch(err){notice.textContent=err.message;notice.hidden=false;b.disabled=false;}
 };
}
async function load(){atlasMetadata=null;atlasRequest++;$('#save-label').textContent='Cargando tu banco…';[bank,state]=await Promise.all([S.loadBank(),S.loadState()]);if(!bank?.questions)throw new Error('No se pudo leer el banco.');index=new Map([...bank.questions,...bank.readings,...bank.flashcards].map(x=>[x.id,x]));ready=true;$('#save-label').textContent=S.local?'Guardado en este dispositivo':S.pending?'Guardado aquí · pendiente de sincronizar':'Sincronizado';render();if(S.pending&&!S.offline&&!S.local)await save();}
async function showOfflineInfo(){const info=await S.offlineInfo();showDialog('Mi sesión descargada',info?`<p>${info.activities} actividades y ${info.images} imágenes. Preparada el ${new Date(info.savedAt).toLocaleString('es-ES')}.</p><p>Abre MIR/27 desde este mismo navegador para estudiar sin conexión. Al salir de tu cuenta se elimina la descarga.</p><button class="ghost" id="remove-offline">Eliminar descarga</button>`:'<p>Abre una sesión y pulsa «Descargar esta sesión». Se guardarán sus preguntas, comentarios e imágenes.</p>');if($('#remove-offline'))$('#remove-offline').onclick=async()=>{await S.removeOffline();$('#dialog').close();toast('Descarga eliminada.');};}
async function showBackups(){const copies=await S.listBackups();showDialog('Copias recientes',`<p>Se conservan hasta tres copias en este navegador. Descarga una para guardarla también fuera del navegador.</p>${copies.map((copy,i)=>`<div class="history-row"><span>${new Date(copy.at).toLocaleString('es-ES')} · ${copy.state.attempts?.length||0} intentos</span><button class="ghost" data-backup="${i}">Descargar copia</button></div>`).join('')||'<p>La primera copia se creará al guardar progreso con conexión.</p>'}`);$('#dialog').querySelectorAll('[data-backup]').forEach(b=>b.onclick=()=>{const c=copies[+b.dataset.backup];download('MIR27-progreso-copia-'+C.dayKey(new Date(c.at))+'.json',c.state);});}
function download(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data)],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function chooseFile(kind){let input=$('#file-input');if(!input){input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.hidden=true;document.body.appendChild(input);}input.value='';input.onchange=async()=>{const f=input.files[0];if(!f)return;if(f.size>85000000)return toast('Archivo demasiado grande.');try{const data=JSON.parse(await f.text());if(kind==='progress'){if(!['mir2027.state.v1','mir2027.state.v2'].includes(data.schema)||!Array.isArray(data.attempts))throw new Error('No es una copia de progreso MIR/27.');if(!confirm('¿Combinar esta copia con tu progreso actual? Se conservarán los intentos distintos de ambas copias.'))return;if(!S.local)await S.backupState(state);state=C.merge(state,data);await save();toast('Progreso combinado.');render();}else{importPayload=data;importView();}}catch(e){toast('No se pudo leer: '+e.message);}};input.click();}
function importView(){if(!ready)return loginView('Entra para autorizar la incorporación del banco documental privado.');if(S.role!=='admin')return shell('Importar banco','<p class="notice warning">Se requiere la cuenta administradora del proyecto.</p>');const b=importPayload;if(b?.schema!=='mir2027.bank.v2'||!Array.isArray(b.questions))return shell('Importación no válida','<p>El archivo no tiene el formato esperado.</p>');shell('Autorizar incorporación privada',`<section class="card"><h2>${b.questions.length.toLocaleString('es-ES')} registros documentales</h2><p>Se enviarán desde este navegador a <strong>tu proyecto Supabase MIR/27</strong>. No se publicarán en GitHub ni se enviarán a Drive.</p><p>${b.sources?.length||0} fichas de fuente · ${Object.keys(b.media||{}).length} imágenes · ${b.readings?.length||0} lecturas.</p><p>Los comentarios conservan la redacción de las fuentes; no se etiquetan como una revisión clínica actual. Tu cuenta y tu progreso se mantienen.</p>${button('confirm-import',importing?'Importando…':'Autorizar e incorporar el banco','primary',importing?'disabled':'')}<div id="import-progress" aria-live="polite"></div><p class="muted small">La importación es por lotes y se puede repetir: actualiza por identificador sin duplicar esos registros.</p></section>`);}
async function doImport(){if(importing)return;importing=true;$('#main [data-action="confirm-import"]').disabled=true;try{const result=await S.importBank(importPayload,p=>{$('#import-progress').innerHTML=`<progress value="${p.processed}" max="${p.total}"></progress><p>${p.processed.toLocaleString('es-ES')} / ${p.total.toLocaleString('es-ES')} registros · ${esc(p.kind)} · ${p.rejected} apartados por validación.</p>`;});if(result.rejected.length){download('MIR27-incidencias-importacion.json',result);toast('Importación realizada con incidencias; se ha descargado el informe.');}else toast('Banco privado incorporado.');importPayload=null;importing=false;history.replaceState(null,'','#bank');await load();}catch(e){importing=false;toast('Importación interrumpida: '+e.message+' Puedes repetirla sin duplicar registros.');importView();}}
function bridge(){const nonce=C.uid().replace(/-/g,'')+C.uid().replace(/-/g,'');const popup=window.open(WEB+'/#import='+nonce,'mir27-import-'+nonce);if(!popup)return toast('Permite abrir la ventana de MIR/27 para autorizar la transferencia.');const listener=e=>{if(e.origin!==WEB||e.source!==popup||e.data?.type!=='MIR27_READY'||e.data?.nonce!==nonce)return;popup.postMessage({type:'MIR27_PRIVATE_BANK',nonce,bank:window.MIR_PRIVATE_BANK},WEB);};window.addEventListener('message',listener);setTimeout(()=>window.removeEventListener('message',listener),15*60000);toast('Se ha abierto tu web. Autoriza allí la incorporación privada. Tu contraseña no se comparte con este archivo.');}
if(importNonce&&/^[a-zA-Z0-9]{25,100}$/.test(importNonce)&&window.opener){window.addEventListener('message',e=>{if(e.source!==window.opener||!['null',WEB].includes(e.origin)||e.data?.type!=='MIR27_PRIVATE_BANK'||e.data?.nonce!==importNonce)return;importPayload=e.data.bank;if(ready)importView();});const signal=()=>window.opener?.postMessage({type:'MIR27_READY',nonce:importNonce},'*');signal();setTimeout(signal,1000);setTimeout(signal,3000);}
function tick(){if(!ready)return;const current=activeS(),el=$('#countdown');if(current?.status==='active'&&current.deadline&&el){const secs=Math.max(0,Math.ceil((current.deadline-Date.now())/1000));el.textContent=`${Math.floor(secs/60)}:${String(secs%60).padStart(2,'0')}`;}let changed=false;for(const s of Object.values(state.sessions)){if(s.status==='active'&&s.mode==='exam'&&s.deadline&&Date.now()>=s.deadline){C.finish(state,s,lookup);changed=true;if(route()==='session'&&current?.id===s.id)resultView(s);}}if(changed){save();toast('Tiempo agotado. El examen se ha entregado.');}}
async function printSession(s,solutions=false){if(!s)return toast('No hay una sesión para imprimir.');if(s.mode==='exam'&&s.status!=='complete'&&solutions)return toast('Entrega el examen antes de imprimir las soluciones.');const printable={...s,items:s.items.map(item=>({...item,data:learningContent(item.data||lookup(item.id))}))};await MIRPrint.open(printable,lookup,id=>S.media(id),{solutions});if(solutions){s.items.forEach(item=>L.expose(state,L.preciseKey(item.data),'solución impresa'));await save();}}
main.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;if(busy&&!['select-option','navigate'].includes(a))return;try{const s=ready?activeS():null;switch(a){case'error-cause':{if(L.classify(state,b.dataset.attempt,b.dataset.cause)){await save();const panel=b.closest('.error-choice');panel.outerHTML=errorChoice(b.dataset.attempt);}break;}case'delayed-start':{const due=L.queue(bank,state).filter(x=>x.ready).slice(0,3);if(!due.length){toast('Todavía no hay casos nuevos con el intervalo cumplido.');break;}start(due.map(x=>x.item),{title:'Recordar con el tiempo',kind:'retention'});break;}case'errors-by-cause':{const ids=new Set(state.attempts.filter(x=>state.errorReviews?.[x.id]?.cause===b.dataset.cause).map(x=>x.itemId));const last=C.latest(state,bank);start(selectItems(bank.questions.filter(q=>C.eligible(q)&&ids.has(q.id)&&last.get(q.id)?.correct===false)),{title:'Repasar: '+L.CAUSES[b.dataset.cause].label});break;}case'prepare-offline':{busy=true;b.disabled=true;try{await MIROffline.ready();await save();const info=await S.prepareOffline(bank,state,s.id);toast('Sesión descargada: '+info.activities+' actividades y '+info.images+' imágenes. Ya puedes abrirla sin conexión en este navegador.');}finally{b.disabled=false;}break;}case'offline-info':await showOfflineInfo();break;case'remove-offline':if(confirm('¿Eliminar la sesión descargada? Tu progreso se conserva.')){await S.removeOffline();$('#dialog').close();toast('Descarga eliminada.');}break;case'backups':await showBackups();break;case'export-backup':{const copies=await S.listBackups(),copy=copies[+b.dataset.index];if(copy)download('MIR27-progreso-copia-'+C.dayKey(new Date(copy.at))+'.json',copy.state);break;}case'retry-load':await load();break;case'navigate':go(b.dataset.view);break;case'daily':daily();break;case'concept-practice':{const items=C.conceptQuestions(bank,state,b.dataset.key,2);start(items,{title:b.dataset.assisted?'Aplicar una idea · con pista':'Comprobar un concepto',kind:'concept',assisted:b.dataset.assisted==='true'});break;}case'resume':currentSession=state.activeSession;go('session');break;case'extra':start(C.selectQuestions(bank,state,+b.dataset.count,Date.now()),{title:'Bloque extra de '+b.dataset.count});break;case'open-question':openQuestion(b.dataset.id);break;case'favorite':state.marks[b.dataset.id]={value:!C.markFor(lookup(b.dataset.id),state)?.value,at:Date.now()};await save();b.textContent=state.marks[b.dataset.id].value?'★ Guardada':'☆ Guardar';break;case'bank-page':filters.page=+b.dataset.page;bankResults();window.scrollTo(0,0);break;case'practice-filter':start(selectItems(filteredQuestions()),{title:'Práctica de mi selección'});break;case'print-filter':{const ps=C.makeSession(bank,state,selectItems(filteredQuestions(),25),{title:'Cuaderno de mi selección'});await printSession(ps,false);break;}case'select-option':if(s&&s.status!=='complete'){const i=s.index||0,old=s.answers[i]||{};if(old.submitted&&s.mode!=='exam')break;s.answers[i]={...old,selected:+b.dataset.index,submitted:false,confidence:$('#confidence')?.value||'unsure',at:Date.now()};if(s.mode==='exam')C.answer(state,s,i,{selected:+b.dataset.index,confidence:$('#confidence')?.value||'unsure',seconds:(Date.now()-enteredAt)/1000},lookup);s.updatedAt=Date.now();main.querySelectorAll('.option').forEach(x=>x.classList.toggle('selected',x===b));save();}break;case'answer':busy=true;await submitAnswer();break;case'blank':busy=true;await submitAnswer(true);break;case'next':busy=true;await next();break;case'previous':if(s){s.index=Math.max(0,(s.index||0)-1);s.updatedAt=Date.now();await save();sessionView();}break;case'jump':if(s){s.index=+b.dataset.index;s.updatedAt=Date.now();await save();sessionView();}break;case'rate':case'read-done':if(s){C.answer(state,s,s.index||0,{rating:a==='rate'?b.dataset.rating:'good',seconds:(Date.now()-enteredAt)/1000},lookup);await save();await next();}break;case'finish-exam':if(s&&confirm('¿Entregar el examen ahora? Las no confirmadas quedarán en blanco.')){C.finish(state,s,lookup);await save();resultView(s);}break;case'subject':start(selectItems(C.selectionPool(bank,state).filter(q=>q.subject===b.dataset.subject)),{title:b.dataset.subject});break;case'reading':start([{kind:'reading',id:b.dataset.id}],{title:'Lectura del material'});break;case'review-study':{const list=bank.questions.filter(q=>C.studyable(q)&&state.studySchedule[q.id]?.dueAt<=Date.now());start(selectItems(list),{title:'Repaso de estudio con observaciones'});break;}case'review-errors':case'review-due':case'review-favorites':{const last=C.latest(state,bank);const list=bank.questions.filter(q=>(a==='review-favorites'?C.studyable(q):C.eligible(q))&&(a==='review-errors'?last.get(q.id)?.correct===false:a==='review-due'?C.scheduleFor(q,state)?.dueAt<=Date.now():C.markFor(q,state)?.value));start(selectItems(list),{title:'Mi repaso dirigido'});break;}case'reading-page':readingPage=+b.dataset.page;readingResults();break;case'atlas-page':atlasPage=+b.dataset.page;atlas();break;case'zoom':await zoom(b.dataset.id);break;case'exam':{const n=+b.dataset.count;start(selectItems(C.selectionPool(bank,state),n),{title:n===210?'Simulacro largo de entrenamiento':'Simulacro de '+n+' preguntas',kind:'exam',mode:'exam',minutes:n===210?270:Math.ceil(n*1.3),mainCount:n===210?200:n});break;}case'numeric':{const items=Array.from({length:5},(_,i)=>{const d=C.numeric(Date.now()+'-'+i);return{id:d.id,kind:'question',data:d};});start(items,{title:'NNT · variantes matemáticas'});break;}case'open-session':currentSession=b.dataset.id;if(state.sessions[currentSession].status==='complete')state.sessions[currentSession].index=0;else state.activeSession=currentSession;go('session');break;case'session-print':await printSession(s,false);break;case'session-print-solutions':await printSession(s,true);break;case'export-progress':download('MIR27-progreso-'+C.dayKey()+'.json',state);break;case'import-progress':chooseFile('progress');break;case'import-file':chooseFile('bank');break;case'export-bank':download('MIR27-banco-documental-privado.json',bank);break;case'confirm-import':await doImport();break;case'bridge':bridge();break;case'note':{const id=b.dataset.id,n=state.notes[id];showDialog('Mi nota',`<textarea id="note-text" rows="7">${esc(typeof n==='string'?n:n?.text||'')}</textarea><button class="primary" data-action="save-note" data-id="${esc(id)}">Guardar nota</button>`);break;}case'report':{const id=b.dataset.id;showDialog('Señalar problema',`<p>Se guardará en tu historial local/privado; no se envía a la editorial.</p><textarea id="report-text" rows="4" placeholder="Explica el problema de la fuente, imagen o pregunta"></textarea><button class="primary" data-action="save-report" data-id="${esc(id)}">Guardar incidencia</button>`);break;}}}catch(err){toast(err.message);}finally{busy=false;}});
$('#dialog').addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='close-dialog')return $('#dialog').close();if(b.dataset.action==='save-note'){state.notes[b.dataset.id]={text:$('#note-text').value,at:Date.now()};await save();$('#dialog').close();toast('Nota guardada.');}if(b.dataset.action==='save-report'){state.reports.push({id:C.uid(),itemId:b.dataset.id,text:$('#report-text').value,at:Date.now()});await save();$('#dialog').close();toast('Incidencia guardada.');}});
$('#nav').onclick=e=>{const b=e.target.closest('[data-view]');if(b)go(b.dataset.view);};$('#logout').onclick=async()=>{await S.signOut();ready=false;bank=null;state=null;index.clear();atlasMetadata=null;atlasRequest++;loginView();};$('#focus').onclick=()=>{if(state){state.preferences.focus=!state.preferences.focus;applyPrefs();save();}};$('#font-minus').onclick=()=>{if(state){state.preferences.fontScale=Math.max(.85,(state.preferences.fontScale||1)-.05);applyPrefs();save();}};$('#font-plus').onclick=()=>{if(state){state.preferences.fontScale=Math.min(1.4,(state.preferences.fontScale||1)+.05);applyPrefs();save();}};
window.addEventListener('hashchange',render);window.addEventListener('online',async()=>{if(!ready||S.local)return;try{await S.reconnect();await save();await load();toast('Conexión recuperada. Tu progreso está sincronizado.');}catch(e){$('#save-label').textContent='Pendiente de sincronizar';toast(e.message);}});document.addEventListener('keydown',e=>{if(e.ctrlKey||e.altKey||e.metaKey||e.target.isContentEditable||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||$('#dialog').open)return;if(/^[1-5]$/.test(e.key)){const opt=main.querySelectorAll('.option:not(:disabled)')[+e.key-1];if(opt){opt.click();e.preventDefault();}}else if(e.key==='Enter'&&route()==='session'){const a=main.querySelector('[data-action="answer"]:not(:disabled)'),n=main.querySelector('[data-action="next"]');(a||n)?.click();e.preventDefault();}else if(e.key.toLowerCase()==='f'&&state){$('#focus').click();}else if(e.key==='Escape'&&state?.preferences.focus){state.preferences.focus=false;applyPrefs();save();}});
setInterval(tick,1000);$('#date-label').textContent=new Intl.DateTimeFormat('es-ES',{dateStyle:'long',timeZone:'Europe/Madrid'}).format(new Date());
(async()=>{try{const ctx=await S.init();if(ctx.recovery)return resetPasswordView();if(route()==='recover')return recoveryView();if(ctx.mode==='local'||ctx.user)await load();else loginView();}catch(e){if(route()==='recover')return recoveryView(e.message);if(S.local||S.user){shell('No se pudo cargar tu espacio',`<section class="card"><p>${esc(e.message)}</p>${button('retry-load','Volver a intentar','primary')}</section>`);}else loginView(e.message);}})();
})();
